import path from 'path';
import os from 'os';
import {
  CODEX_SKILL_CONTENT,
  CODEX_SKILL_MARKER,
} from '../utils/skills/codex-skill';
import {
  hasAgentSkill,
  removeAgentSkill,
  writeAgentSkill,
  type AgentSkill,
  type SkillResult,
} from './agentSkill';

export const codexSkillPath = (homeDir: string = os.homedir()): string =>
  path.join(homeDir, '.agents', 'skills', 'rivet', 'SKILL.md');

const codexSkill = (homeDir: string): AgentSkill => ({
  filePath: codexSkillPath(homeDir),
  content: CODEX_SKILL_CONTENT,
  marker: CODEX_SKILL_MARKER,
});

export const hasCodexSkill = (homeDir: string = os.homedir()): boolean =>
  hasAgentSkill(codexSkill(homeDir));

export const writeCodexSkill = (homeDir: string = os.homedir()): SkillResult =>
  writeAgentSkill(codexSkill(homeDir));

export const removeCodexSkill = (homeDir: string = os.homedir()): SkillResult =>
  removeAgentSkill(codexSkill(homeDir));
